package registry

import (
	"maps"
	"math"
	"slices"
)

// Environment attribute layers are generated by tools/gen registrytables.

var (
	posInf = float32(math.Inf(1))
	negInf = float32(math.Inf(-1))
)

// EnvAttribute is a minecraft:environment_attribute entry. Float is
// AttributeType.toFloat's presence. Discrete encodes booleans as 0/1 and
// TriState.DEFAULT as -1; these tracks use constant interpolation. Min and Max
// bound sanitizeValue (infinite when unbounded).
type EnvAttribute struct {
	Float, Positional, Discrete bool
	Default, Min, Max           float32
}

// EnvAttributeByName looks up an environment attribute by its full name.
func EnvAttributeByName(name string) (EnvAttribute, bool) {
	a, ok := envAttributes[name]
	return a, ok
}

// EnvAttributeNames returns the supported registry's attribute names.
func EnvAttributeNames() []string { return slices.Sorted(maps.Keys(envAttributes)) }

// Sanitize clamps a value into the attribute's range.
// vanilla: AttributeRange.ofFloat
func (a EnvAttribute) Sanitize(v float32) float32 {
	if v >= a.Min && v <= a.Max {
		return v
	}
	return min(max(v, a.Min), a.Max)
}

// EnvFloatOp is a numeric or boolean attribute modifier.
// vanilla: AttributeModifier.FLOAT_LIBRARY, FloatModifier
type EnvFloatOp uint8

const (
	EnvOverride EnvFloatOp = iota
	EnvAlphaBlend
	EnvAdd
	EnvSubtract
	EnvMultiply
	EnvMinimum
	EnvMaximum
	EnvAnd
	EnvNand
	EnvOr
	EnvNor
	EnvXor
	EnvXnor
)

// EnvFloatEntry is a modifier with its argument; Alpha is 1 except for
// alpha_blend's FloatWithAlpha.
type EnvFloatEntry struct {
	Op           EnvFloatOp
	Value, Alpha float32
}

// EnvLerp is Mth.lerp in float32, the float attributes' interpolation; the
// product is rounded before the sum so it is never fused.
func EnvLerp(delta, from, to float32) float32 { return from + float32(delta*(to-from)) }

// Apply modifies v by the entry.
func (e EnvFloatEntry) Apply(v float32) float32 {
	if e.Op >= EnvAnd {
		a, b := v != 0, e.Value != 0
		result := false
		switch e.Op {
		case EnvAnd:
			result = a && b
		case EnvNand:
			result = !a || !b
		case EnvOr:
			result = a || b
		case EnvNor:
			result = !a && !b
		case EnvXor:
			result = a != b
		case EnvXnor:
			result = a == b
		}
		if result {
			return 1
		}
		return 0
	}
	switch e.Op {
	case EnvAlphaBlend:
		return EnvLerp(e.Alpha, v, e.Value)
	case EnvAdd:
		return v + e.Value
	case EnvSubtract:
		return v - e.Value
	case EnvMultiply:
		return v * e.Value
	case EnvMinimum:
		return min(v, e.Value)
	case EnvMaximum:
		return max(v, e.Value)
	}
	return e.Value
}

// EnvDimensionFloat is the dimension type's own entry for a float attribute.
func EnvDimensionFloat(dimensionType, attribute string) (EnvFloatEntry, bool) {
	e, ok := envDimensionFloats[dimensionType][attribute]
	return e, ok
}

// EnvBiomeFloat is the biome's entry for a float attribute.
func EnvBiomeFloat(biome, attribute string) (EnvFloatEntry, bool) {
	e, ok := envBiomeFloats[biome][attribute]
	return e, ok
}

// EnvBiomeHasFloat reports whether any biome supplies this attribute's layer.
func EnvBiomeHasFloat(attribute string) bool {
	for _, entries := range envBiomeFloats {
		if _, ok := entries[attribute]; ok {
			return true
		}
	}
	return false
}

// EnvTimelines are the dimension type's timelines in its holder set's order,
// the order their layers apply in.
func EnvTimelines(dimensionType string) []EnvTimeline { return envTimelines[dimensionType] }

// EnvTimelineByName returns a built-in timeline's supported tracks.
func EnvTimelineByName(name string) (EnvTimeline, bool) {
	t, ok := envNamedTimelines[name]
	return t, ok
}

// EnvTimeline is a timeline's clock, period (0 for none) and supported tracks.
type EnvTimeline struct {
	Clock  string
	Period int32
	Tracks map[string]EnvFloatTrack
}

// EnvFloatTrack is a timeline track of a float attribute: the modifier
// whose argument the keyframes give.
type EnvFloatTrack struct {
	Op        EnvFloatOp
	Ease      EnvEase
	Keyframes []EnvKeyframe
}

// EnvKeyframe is a keyframe's tick and modifier argument.
type EnvKeyframe struct {
	Ticks        int32
	Value, Alpha float32
}

// EnvEaseKind is a keyframe track's easing; the zero value is linear.
type EnvEaseKind uint8

const (
	EnvEaseLinear EnvEaseKind = iota
	EnvEaseConstant
	EnvEaseCubicBezier
)

// EnvEase is an easing with its cubic bezier controls x1, y1, x2, y2.
type EnvEase struct {
	Kind     EnvEaseKind
	Controls [4]float32
}

// Apply eases a segment's progress.
// vanilla: EasingType
func (e EnvEase) Apply(x float32) float32 {
	switch e.Kind {
	case EnvEaseConstant:
		return 0
	case EnvEaseCubicBezier:
		c := e.Controls
		xc, yc := bezierCurve(c[0], c[2]), bezierCurve(c[1], c[3])
		return yc.sample(xc.solve(x))
	}
	return x
}

// cubicCurve is a bezier coordinate's polynomial ((a t + b) t + c) t.
// vanilla: EasingType.CubicBezier.CubicCurve
type cubicCurve struct{ a, b, c float32 }

// The products are rounded to float32 on their own so none is fused into an
// FMA, which Java's float arithmetic never does.
func bezierCurve(v1, v2 float32) cubicCurve {
	return cubicCurve{float32(3*v1) - float32(3*v2) + 1, float32(-6*v1) + float32(3*v2), float32(3 * v1)}
}

func (c cubicCurve) sample(t float32) float32 {
	v := float32(c.a*t) + c.b
	v = float32(v*t) + c.c
	return v * t
}

func (c cubicCurve) gradient(t float32) float32 {
	v := float32(float32(3*c.a)*t) + float32(2*c.b)
	return float32(v*t) + c.c
}

// solve finds t where the curve reaches x: Newton steps of at most 0.25,
// then bisection.
// vanilla: EasingType.CubicBezier.solveT, solveTBisect
func (c cubicCurve) solve(x float32) float32 {
	t := x
	for range 4 {
		e := c.sample(t) - x
		if float32(math.Abs(float64(e))) < 1e-5 {
			return t
		}
		g := c.gradient(t)
		if g < 1e-5 {
			break
		}
		t -= min(max(e/g, -0.25), 0.25)
	}
	t0, t1 := float32(0), float32(1)
	for t0 < t1 {
		e := c.sample(t) - x
		if float32(math.Abs(float64(e))) < 1e-5 {
			return t
		}
		if e < 0 {
			t0 = t
		} else {
			t1 = t
		}
		t = (t1 + t0) / 2
	}
	return t
}

// Sample is the track's modifier entry at a clock's total ticks: a periodic
// track wraps, with segments joining the last keyframe to the first across
// the period's ends.
// vanilla: KeyframeTrackSampler
func (t EnvFloatTrack) Sample(ticks int64, period int32) EnvFloatEntry {
	k := t.Keyframes
	entry := func(f EnvKeyframe) EnvFloatEntry { return EnvFloatEntry{Op: t.Op, Value: f.Value, Alpha: f.Alpha} }
	if len(k) == 1 {
		return entry(k[0])
	}
	if period > 0 {
		ticks = ((ticks % int64(period)) + int64(period)) % int64(period)
	}
	s := t.segmentAt(ticks, period)
	switch {
	case ticks <= s.fromTick:
		return entry(s.from)
	case ticks >= s.toTick:
		return entry(s.to)
	}
	alpha := t.Ease.Apply(float32(ticks-s.fromTick) / float32(s.toTick-s.fromTick))
	return EnvFloatEntry{Op: t.Op, Value: EnvLerp(alpha, s.from.Value, s.to.Value), Alpha: EnvLerp(alpha, s.from.Alpha, s.to.Alpha)}
}

// envSegment is the stretch between two keyframes a track interpolates over.
type envSegment struct {
	from, to         EnvKeyframe
	fromTick, toTick int64
}

// segmentAt is the first segment ending after ticks (already wrapped into the
// period): the wrap from the last keyframe into the first, each pair in turn,
// then the wrap from the last into the next period's first. With none, the
// last one.
func (t EnvFloatTrack) segmentAt(ticks int64, period int32) envSegment {
	k := t.Keyframes
	first, last := k[0], k[len(k)-1]
	if period > 0 && ticks < int64(first.Ticks) {
		return envSegment{last, first, int64(last.Ticks - period), int64(first.Ticks)}
	}
	for i := range len(k) - 1 {
		if ticks < int64(k[i+1].Ticks) || period <= 0 && i == len(k)-2 {
			return envSegment{k[i], k[i+1], int64(k[i].Ticks), int64(k[i+1].Ticks)}
		}
	}
	return envSegment{last, first, int64(last.Ticks), int64(first.Ticks + period)}
}
